<script setup lang="ts">
import { useProjectRegister, useDeleteProjectRegister } from '@/composables/useProjectGovernance'
import { governanceFilters } from '@/components/project/governance/state'
import { ApiError } from '@/composables/useApi'
const route = useRoute(); const router = useRouter(); const { t } = useI18n(); const hydrated = useHydrated()
const id = computed(() => Number(route.params.id))
const parsed = computed(() => governanceFilters(route.query))
const filters = computed(() => (parsed.value))
const list = useProjectRegister(id, filters); const remove = useDeleteProjectRegister()
const confirmDeleteId = ref<number | null>(null); const error = ref<string | null>(null)
const returnTo = computed(() => route.fullPath)
function setFilter(key: string, value: string) { router.replace({ query: { ...route.query, [key]: value || undefined, offset: undefined } }) }
const q = computed({ get: () => typeof route.query.q === 'string' ? route.query.q : '', set: value => setFilter('q', value) })
const kind = computed({ get: () => parsed.value.kind ?? '', set: value => setFilter('kind', value) })
const status = computed({ get: () => parsed.value.status ?? '', set: value => setFilter('status', value) })
const priority = computed({ get: () => parsed.value.priority ?? '', set: value => setFilter('priority', value) })
function page(delta: number) { router.push({ query: { ...route.query, offset: String(Math.max(0, (parsed.value.offset ?? 0) + delta * 50)) } }) }
async function deleteItem(item: { id: number }) {
  error.value = null
  if (confirmDeleteId.value !== item.id) { confirmDeleteId.value = item.id; return }
  try { await remove.mutateAsync({ projectId: id.value, id: item.id }); confirmDeleteId.value = null }
  catch (cause) { error.value = cause instanceof ApiError && cause.code === 'stakeholder_assigned' ? t('projects.governance.stakeholderAssigned') : cause instanceof ApiError ? cause.message : t('errors.generic') }
}
</script>
<template><div class="nasq-page-stack mx-auto w-full max-w-6xl"><SharedPageHeader :title="t('projects.governance.register.title')" :back-to="`/projects/${id}`" /><div class="flex flex-wrap items-center gap-3"><Input :aria-label="t('app.search')" :disabled="!hydrated" v-model="q" class="max-w-sm" :placeholder="t('app.search')" /><select :aria-label="t('projects.governance.register.kind')" :disabled="!hydrated" v-model="kind" class="nasq-input"><option value="">{{ t('projects.governance.all') }}</option><option value="risk">{{ t('projects.governance.register.risk') }}</option><option value="issue">{{ t('projects.governance.register.issue') }}</option></select><select :aria-label="t('projects.governance.register.status')" :disabled="!hydrated" v-model="status" class="nasq-input"><option value="">{{ t('projects.governance.all') }}</option><option value="open">{{ t('projects.governance.register.open') }}</option><option value="in_progress">{{ t('projects.governance.register.inProgress') }}</option><option value="resolved">{{ t('projects.governance.register.resolved') }}</option><option value="closed">{{ t('projects.governance.register.closed') }}</option></select><select v-model="priority" class="nasq-input" :aria-label="t('projects.governance.register.priority')" :disabled="!hydrated"><option value="">{{ t('projects.governance.all') }}</option><option v-for="value in ['low', 'normal', 'high', 'critical']" :key="value" :value="value">{{ t(`projects.governance.register.${value}`) }}</option></select><NuxtLink v-if="list.data.value?.can_manage && hydrated" :to="{ path: `/projects/${id}/register/new`, query: { returnTo } }"><Button>{{ t('app.create') }}</Button></NuxtLink></div><p v-if="error" role="alert" class="text-sm text-destructive">{{ error }}</p><SharedPageState :loading="list.isLoading.value" :error="list.error.value" :empty="!list.isLoading.value && !list.data.value?.items.length" @retry="list.refetch" /><section v-if="list.data?.value?.items.length" class="nasq-panel overflow-x-auto"><table class="w-full text-start text-sm"><thead><tr class="border-b"><th class="p-3 text-start">{{ t('projects.governance.register.itemTitle') }}</th><th class="p-3 text-start">{{ t('projects.governance.register.kind') }}</th><th class="p-3 text-start">{{ t('projects.governance.register.priority') }}</th><th class="p-3 text-start">{{ t('projects.governance.register.status') }}</th><th class="p-3 text-start">{{ t('projects.governance.register.score') }}</th><th class="p-3 text-end" /></tr></thead><tbody><tr v-for="item in list.data.value.items" :key="item.id" class="border-b last:border-0"><td class="p-3"><NuxtLink class="font-medium underline" :to="{ path: `/projects/${id}/register/${item.id}`, query: { returnTo } }">{{ item.title }}</NuxtLink></td><td class="p-3">{{ t(`projects.governance.register.${item.kind}`) }}</td><td class="p-3">{{ t(`projects.governance.register.${item.priority}`) }}</td><td class="p-3">{{ t(`projects.governance.register.${item.status}`) }}</td><td class="p-3">{{ item.score ?? '—' }}</td><td v-if="list.data.value.can_manage" class="p-3 text-end"><Button variant="ghost" size="sm" :disabled="!hydrated || remove.isPending.value" @click="deleteItem(item)">{{ confirmDeleteId === item.id ? t('projects.governance.confirmDeleteAction') : t('projects.governance.delete') }}</Button><Button v-if="confirmDeleteId === item.id" variant="outline" size="sm" :disabled="!hydrated || remove.isPending.value" @click="confirmDeleteId = null">{{ t('app.cancel') }}</Button></td></tr></tbody></table></section><nav v-if="list.data.value" class="flex items-center gap-3" :aria-label="t('projects.governance.pagination')"><Button variant="outline" :disabled="!hydrated || list.isFetching.value || !parsed.offset" @click="page(-1)">{{ t('projects.governance.previous') }}</Button><span>{{ t('projects.governance.total', { total: list.data.value.total }) }}</span><Button variant="outline" :disabled="!hydrated || list.isFetching.value || (parsed.offset ?? 0) + 50 >= list.data.value.total" @click="page(1)">{{ t('projects.governance.next') }}</Button></nav></div></template>
